<template>
  <div class="lab">
    <form class="lab-form" @submit.prevent="runLab">
      <input
        v-model="labQuery"
        class="lab-input"
        type="text"
        autocomplete="off"
        spellcheck="false"
        placeholder="Try a question"
        aria-label="Question for the search comparison"
      >
      <button type="submit" class="lab-go" :disabled="labBusy">{{ labBusy ? '…' : 'Compare' }}</button>
    </form>
    <div class="lab-samples">
      <button
        v-for="s in labSamples"
        :key="s"
        type="button"
        class="lab-chip"
        :disabled="labBusy"
        @click="labQuery = s; runLab();"
      >{{ s }}</button>
    </div>
    <p v-if="labStatus" class="lab-status">{{ labStatus }}</p>

    <div v-if="fusedTop.length" class="lab-columns">
      <div class="lab-col">
        <p class="lab-col-title">Word match</p>
        <p class="lab-col-sub">lexical ranking</p>
        <ol>
          <li v-for="r in lexTop" :key="`l${r.id}`">
            <span class="lab-hit-title">{{ r.title }}</span>
            <span class="lab-bar"><span class="lab-bar-fill" :style="{ width: r.pct + '%' }"></span></span>
          </li>
          <li v-if="!lexTop.length" class="lab-none">No word overlap at all.</li>
        </ol>
      </div>
      <div class="lab-col">
        <p class="lab-col-title">Meaning match</p>
        <p class="lab-col-sub">semantic similarity</p>
        <ol>
          <li v-for="r in semTop" :key="`s${r.id}`">
            <span class="lab-hit-title">{{ r.title }}</span>
            <span class="lab-bar"><span class="lab-bar-fill" :style="{ width: r.pct + '%' }"></span></span>
          </li>
        </ol>
      </div>
      <div class="lab-col lab-col-fused">
        <p class="lab-col-title">Combined</p>
        <p class="lab-col-sub">what Search uses</p>
        <ol>
          <li v-for="r in fusedTop" :key="`f${r.id}`">
            <span class="lab-hit-title">{{ r.title }}</span>
            <span class="lab-badges">{{ r.badge }}</span>
          </li>
        </ol>
      </div>
    </div>

    <div v-if="scores.length" class="floor-demo">
      <div class="floor-strip" aria-hidden="true">
        <span
          v-for="(s, i) in scores"
          :key="i"
          class="floor-dot"
          :class="{ pass: s >= floor }"
          :style="{ left: scoreX(s) + '%' }"
        ></span>
        <span class="floor-line" :style="{ left: scoreX(floor) + '%' }"></span>
      </div>
      <div class="floor-controls">
        <input v-model.number="floor" type="range" min="0" max="0.6" step="0.005" aria-label="Minimum relevance">
        <p class="floor-readout">
          minimum relevance {{ floor.toFixed(3) }} · <strong>{{ passCount }}</strong> of {{ scores.length }} passages
          remain<span v-if="Math.abs(floor - defaultFloor) > 0.002"> (the site normally uses {{ defaultFloor }})</span>
        </p>
      </div>
    </div>
    <p v-else-if="scoresAttempted" class="floor-empty">Run a query above and the score distribution appears here.</p>
  </div>
</template>

<script>
import { loadSearchItems, lexicalRank, rrfFuse } from '../../utils/askRetrieval';
import { ensureReady, semanticScores, SCORE_FLOOR } from '../../utils/semanticSearch';

export default {
  name: 'RetrievalLab',
  data() {
    return {
      labQuery: '',
      labBusy: false,
      labStatus: '',
      labSamples: ['learning new words every day', 'HSBC', 'where has Henry lived?'],
      lexTop: [],
      semTop: [],
      fusedTop: [],
      scores: [],
      scoresAttempted: false,
      floor: SCORE_FLOOR,
      defaultFloor: SCORE_FLOOR,
      corpusSize: 0,
    };
  },
  computed: {
    passCount() {
      return this.scores.filter((s) => s >= this.floor).length;
    },
  },
  mounted() {
    loadSearchItems().then((items) => { this.corpusSize = items.length; }).catch(() => {});
  },
  methods: {
    scoreX(s) {
      const lo = -0.05;
      const hi = 0.7;
      return Math.max(0, Math.min(100, ((s - lo) / (hi - lo)) * 100));
    },
    cleanTitle(t) {
      return String(t || '').replace(/\s+\(\d+\)$/, '');
    },
    async runLab() {
      const q = this.labQuery.trim();
      if (!q || this.labBusy) return;
      this.labBusy = true;
      this.scoresAttempted = true;
      this.labStatus = 'Warming up the on-device model (the first run downloads it to your browser)…';
      try {
        const items = await loadSearchItems();
        this.corpusSize = items.length;
        const byId = {};
        for (const it of items) byId[it.id] = it;

        await ensureReady();
        this.labStatus = '';
        const all = await semanticScores(q);
        const lex = lexicalRank(q, items);
        const fusedIds = rrfFuse(lex, all.slice(0, 12).map((h) => ({ id: h.id }))).slice(0, 8);

        const lexRank = new Map(lex.map((x, i) => [x.id, i + 1]));
        const semRank = new Map(all.map((x, i) => [x.id, i + 1]));
        const maxLex = lex.length ? lex[0].s : 1;
        const maxSem = all.length ? Math.max(all[0].score, 0.001) : 1;

        this.lexTop = lex.slice(0, 5).map((x) => ({
          id: x.id,
          title: this.cleanTitle(byId[x.id] && byId[x.id].title),
          pct: Math.round((x.s / maxLex) * 100),
        }));
        this.semTop = all.slice(0, 5).map((x) => ({
          id: x.id,
          title: this.cleanTitle(byId[x.id] && byId[x.id].title),
          pct: Math.round((Math.max(x.score, 0) / maxSem) * 100),
        }));
        this.fusedTop = fusedIds.slice(0, 5).map((id) => ({
          id,
          title: this.cleanTitle(byId[id] && byId[id].title),
          badge: `${lexRank.has(id) ? 'L' + lexRank.get(id) : 'L–'} · S${semRank.get(id)}`,
        }));
        this.scores = all.map((x) => x.score);
      } catch (e) {
        this.labStatus = 'Meaning match is temporarily unavailable. Try again in a moment.';
      } finally {
        this.labBusy = false;
      }
    },
  },
};
</script>

