@media (prefers-reduced-motion: reduce) {
  .view-fade-enter-active,
  .view-fade-leave-active {
    transition: opacity 0.1s ease;
  }
  .view-fade-enter-from,
  .view-fade-leave-to {
    transform: none;
  }
}

